import type { Step } from "./types.ts";

/** @docs/core/client-setup.md, generated from the step list: the guide cannot drift from the checks. */
export function renderClientSetup(steps: Step[]): string {
  const out: string[] = [
    "# Client setup",
    "",
    "<!-- Generated by `pnpm hub docs` from app/apps/installer/src/steps. Do not edit; change the step instead. -->",
    "",
    "Manual-first (owner decision 2026-11-14, a decision or plan record kept in the owner's instance): you start a Claude Code session with `hub agent` (or Claude Desktop) and hand it ONE instruction, for example \"разбери почту проекта X\". Nothing runs in the background. The phrases are in `skills/README.md`.",
    "",
    "Quickstart: make an instance (`@docs/LAYERS.md`), then from it `./run.sh setup`, `./run.sh agent <project>`, say the phrase. Setup ends with `ready: run hub agent`.",
    "",
    "Commands: `./run.sh <command>` from the instance folder (it sets `HUB_HOME` and runs the pinned core in `core/`). `hub <command>` works the same when `HUB_HOME` is exported and `hub` is on your PATH. Developers can also run `pnpm hub <command>` in the core's `app/` with `HUB_HOME` set.",
    "",
    "- `hub setup` is minimal and tokenless: tools, folders, config, skills, project registry, then the doctor table. Rerun any time; existing config is never overwritten.",
    "- `hub doctor` runs only the checks a manual session needs and prints a pass/fail table (nothing is changed). The optional steps below never fail it.",
    "- `hub guide` prints the manual steps; `hub install --dry-run` shows what would change.",
    "- `hub setup --automation` (and `--automation` on `install`, `doctor`, `guide`) adds the OPTIONAL extras (Notion token, mail login, Telegram poller), OFF by default.",
    "- Secrets (mail logins, optional tokens) live in the git-ignored `state/secrets/` (folder mode 700, files 600), never in a tracked file, a plist or a log. `HUB_CONFIG_DIR` overrides the folder.",
    "",
  ];
  const section = (steps: Step[]) => {
    let group = "";
    for (const s of steps) {
      if (s.group !== group) { group = s.group; out.push(`## ${group}`, ""); }
      out.push(`### ${s.title}`, "", `Step id: \`${s.id}\``, "", `**Why.** ${s.why}`, "");
      if (s.manual) out.push("**You do this** (the installer cannot):", "", ...s.manual.steps.map((t, i) => `${i + 1}. ${t}`), "");
      else if (s.does) out.push(`**The installer does.** ${s.does}`, "");
      out.push(`**Verified by.** ${s.verifies}`, "");
    }
  };
  section(steps.filter((s) => !s.optional));
  const auto = steps.filter((s) => s.optional === "automation");
  if (auto.length) {
    out.push("# Optional extras (OFF)", "", "Not needed for manual sessions. These steps (Notion token, mail login, Telegram poller) run only with `--automation`; nothing here is required.", "");
    section(auto);
  }
  const dev = steps.filter((s) => s.optional === "dev");
  if (dev.length) {
    out.push("# Optional: UI development", "", "Only for whoever changes the local app's screens. Run with `pnpm hub install --only <step id>`.", "");
    section(dev);
  }
  return out.join("\n").replace(/\n{3,}/g, "\n\n").trimEnd() + "\n";
}

/** The line every page that lists checks ends with (the architecture-change rule, CLAUDE.md). */
export const UPDATE_LINE = "Update this page when the architecture changes.";

const FLAG: Record<NonNullable<Step["optional"]>, string> = { automation: "optional extra, `--automation`", dev: "UI development only" };

/**
 * @docs/setup/checklist.md: the working-order checklist of every node (tools, files, mail, Notion, server, backups), generated from
 * the step list, so a check that is added, renamed or removed changes this page in the same change. Order = the order doctor runs.
 */
export function renderChecklist(steps: Step[]): string {
  const out: string[] = [
    "# Setup checklist",
    "",
    "<!-- Generated by `pnpm hub docs` from app/apps/installer/src/steps. Do not edit; change the step instead. -->",
    "",
    "Work top to bottom. `hub doctor` runs every box below that is not an optional extra and prints PASS, WARN or FAIL per step id; `hub doctor --automation` adds the extras. A FAIL names its own fix. `hub guide` prints the by-hand steps. Which access goes to what: `@docs/setup/access.md`.",
    "",
  ];
  let group = "";
  for (const s of steps) {
    if (s.group !== group) { group = s.group; out.push(`## ${group}`, ""); }
    const flag = s.optional ? FLAG[s.optional] : s.audit ? "`hub doctor` only; setup and install never run it" : "";
    out.push(`- [ ] **${s.title}** (\`${s.id}\`${flag ? `; ${flag}` : ""})`, `  - Proves: ${s.verifies}`);
    if (s.manual) out.push(`  - You: ${s.manual.steps.join(" ")}`);
    else if (s.does) out.push(`  - \`hub install\` fixes it: ${s.does}`);
  }
  out.push("", UPDATE_LINE);
  return out.join("\n") + "\n";
}
